-- Consolidated snapshot of all migrations (currently 0001). Generated by copying, guarded by tests/unit/test_schema.py. Do not edit by hand.
-- Conventions: enums are CHECK constraints, booleans are INTEGER 0/1, dates are TEXT YYYY-MM-DD,
-- timestamps are TEXT ISO-8601 UTC with a trailing Z. Every foreign key is ON DELETE RESTRICT
-- (nothing is ever deleted, BR-08/BR-16, the only deletion is the provisional-person merge of 10.2a(d),
-- which first re-points every reference). There is deliberately NO column holding an email body,
-- subject or message text (GM-10).

CREATE TABLE schema_version (
    version    INTEGER PRIMARY KEY CHECK (version >= 1),
    name       TEXT NOT NULL,
    applied_at TEXT NOT NULL
);

-- person.id is the stable slug derived from identity_key (spec 10.2a, for example priya-nair).
CREATE TABLE person (
    id           TEXT PRIMARY KEY,
    first_name   TEXT NOT NULL,
    last_name    TEXT,
    qualifier    TEXT,
    display_name TEXT NOT NULL,
    name_key     TEXT NOT NULL,
    identity_key TEXT NOT NULL UNIQUE,
    email        TEXT,
    origin       TEXT NOT NULL CHECK (origin IN ('roster', 'attendee', 'note_owner')),
    verified     INTEGER NOT NULL DEFAULT 0 CHECK (verified IN (0, 1))
);

CREATE TABLE person_alias (
    person_id TEXT NOT NULL REFERENCES person(id) ON DELETE RESTRICT,
    alias     TEXT NOT NULL,
    alias_key TEXT NOT NULL,
    PRIMARY KEY (person_id, alias_key)
);

CREATE TABLE ingest_run (
    id                      INTEGER PRIMARY KEY AUTOINCREMENT,
    started_at              TEXT NOT NULL,
    finished_at             TEXT,
    folder_root             TEXT NOT NULL,
    status                  TEXT NOT NULL DEFAULT 'in_progress'
                            CHECK (status IN ('in_progress', 'complete', 'partial', 'interrupted')),
    dry_run                 INTEGER NOT NULL DEFAULT 0 CHECK (dry_run IN (0, 1)),
    files_discovered        INTEGER NOT NULL DEFAULT 0,
    files_ingested          INTEGER NOT NULL DEFAULT 0,
    files_unchanged         INTEGER NOT NULL DEFAULT 0,
    files_empty             INTEGER NOT NULL DEFAULT 0,
    files_failed            INTEGER NOT NULL DEFAULT 0,
    items_new               INTEGER NOT NULL DEFAULT 0,
    items_merged            INTEGER NOT NULL DEFAULT 0,
    items_updated           INTEGER NOT NULL DEFAULT 0,
    items_unchanged         INTEGER NOT NULL DEFAULT 0,
    possible_duplicates     INTEGER NOT NULL DEFAULT 0,
    already_done_in_note    INTEGER NOT NULL DEFAULT 0,
    resolved_via_attendance INTEGER NOT NULL DEFAULT 0
);

-- mtime is the file modification time as an ISO-8601 UTC timestamp.
-- rel_path and folder_root are stored verbatim (filesystem names are never normalised).
CREATE TABLE source_file (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    folder_root       TEXT NOT NULL,
    rel_path          TEXT NOT NULL,
    content_sha256    TEXT,
    size_bytes        INTEGER,
    mtime             TEXT,
    status            TEXT NOT NULL CHECK (status IN ('ok', 'empty', 'failed', 'missing')),
    failure_code      TEXT,
    last_run_id       INTEGER REFERENCES ingest_run(id) ON DELETE RESTRICT,
    first_seen_run    INTEGER REFERENCES ingest_run(id) ON DELETE RESTRICT,
    last_ingested_run INTEGER REFERENCES ingest_run(id) ON DELETE RESTRICT,
    UNIQUE (folder_root, rel_path)
);

CREATE TABLE ingest_warning (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id         INTEGER NOT NULL REFERENCES ingest_run(id) ON DELETE RESTRICT,
    source_file_id INTEGER REFERENCES source_file(id) ON DELETE RESTRICT,
    line           INTEGER,
    code           TEXT NOT NULL,
    message        TEXT NOT NULL
);

CREATE TABLE meeting (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    source_file_id INTEGER NOT NULL UNIQUE REFERENCES source_file(id) ON DELETE RESTRICT,
    meeting_date   TEXT,
    date_source    TEXT NOT NULL
                   CHECK (date_source IN ('front_matter', 'date_line', 'title', 'filename', 'none')),
    title          TEXT
);

CREATE TABLE meeting_attendee (
    meeting_id INTEGER NOT NULL REFERENCES meeting(id) ON DELETE RESTRICT,
    raw_name   TEXT NOT NULL,
    person_id  TEXT REFERENCES person(id) ON DELETE RESTRICT,
    email_hint TEXT,
    PRIMARY KEY (meeting_id, raw_name)
);

-- completion_evidence_source_id points at item_source (declared below, SQLite allows the forward reference).
CREATE TABLE action_item (
    id                            INTEGER PRIMARY KEY AUTOINCREMENT,
    description                   TEXT NOT NULL,
    task_text                     TEXT NOT NULL,
    description_core_key          TEXT NOT NULL,
    status                        TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'done')),
    completion_origin             TEXT CHECK (completion_origin IS NULL OR completion_origin IN ('note', 'manual')),
    completed_at                  TEXT,
    completion_evidence_source_id INTEGER REFERENCES item_source(id) ON DELETE RESTRICT,
    due_raw                       TEXT,
    due_raw_other                 TEXT,
    due_date                      TEXT,
    due_confidence                TEXT NOT NULL DEFAULT 'none'
                                  CHECK (due_confidence IN ('explicit', 'relative', 'inferred', 'unresolved', 'none')),
    due_rule                      TEXT CHECK (due_rule IS NULL OR due_rule IN (
        'iso_date', 'text_date', 'numeric_date', 'yearless_date', 'weekday_date', 'event_date',
        'day_of_month', 'today', 'eod_alone', 'tomorrow', 'yesterday', 'weekday_next', 'weekday_this',
        'weekday_next_week', 'monday_next_week', 'end_of_week', 'end_of_next_week', 'end_of_month',
        'end_of_next_month', 'in_n_days', 'in_n_weeks')),
    due_reason                    TEXT CHECK (due_reason IS NULL OR due_reason IN (
        'no_meeting_date', 'vague', 'range', 'same_weekday', 'this_weekday_past', 'weekend_meeting',
        'ambiguous_numeric', 'invalid_date', 'weekday_date_mismatch', 'multiple_dates')),
    source_state                  TEXT NOT NULL DEFAULT 'present' CHECK (source_state IN ('present', 'missing')),
    created_at                    TEXT NOT NULL,
    updated_at                    TEXT NOT NULL
);

-- raw_text is VERBATIM (not NFC) and block_hash is computed over it. The columns from description
-- to due_reason are the per-source parse results (10.6 matching, 10.7.2 pairing).
CREATE TABLE item_source (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    item_id          INTEGER NOT NULL REFERENCES action_item(id) ON DELETE RESTRICT,
    source_file_id   INTEGER NOT NULL REFERENCES source_file(id) ON DELETE RESTRICT,
    meeting_id       INTEGER REFERENCES meeting(id) ON DELETE RESTRICT,
    line_start       INTEGER NOT NULL,
    line_end         INTEGER NOT NULL,
    raw_text         TEXT NOT NULL,
    section_heading  TEXT,
    checkbox_state   TEXT NOT NULL CHECK (checkbox_state IN ('open', 'done')),
    occurrence_index INTEGER NOT NULL DEFAULT 0,
    block_hash       TEXT NOT NULL,
    present          INTEGER NOT NULL DEFAULT 1 CHECK (present IN (0, 1)),
    first_seen_run   INTEGER REFERENCES ingest_run(id) ON DELETE RESTRICT,
    last_seen_run    INTEGER REFERENCES ingest_run(id) ON DELETE RESTRICT,
    description      TEXT,
    task_text        TEXT,
    core_key         TEXT,
    due_raw          TEXT,
    due_raw_other    TEXT,
    due_date         TEXT,
    due_confidence   TEXT NOT NULL DEFAULT 'none'
                     CHECK (due_confidence IN ('explicit', 'relative', 'inferred', 'unresolved', 'none')),
    due_rule         TEXT CHECK (due_rule IS NULL OR due_rule IN (
        'iso_date', 'text_date', 'numeric_date', 'yearless_date', 'weekday_date', 'event_date',
        'day_of_month', 'today', 'eod_alone', 'tomorrow', 'yesterday', 'weekday_next', 'weekday_this',
        'weekday_next_week', 'monday_next_week', 'end_of_week', 'end_of_next_week', 'end_of_month',
        'end_of_next_month', 'in_n_days', 'in_n_weeks')),
    due_reason       TEXT CHECK (due_reason IS NULL OR due_reason IN (
        'no_meeting_date', 'vague', 'range', 'same_weekday', 'this_weekday_past', 'weekend_meeting',
        'ambiguous_numeric', 'invalid_date', 'weekday_date_mismatch', 'multiple_dates'))
);

-- Per-source owner phrases as child rows (decision of task T-M1-10: queryable by the whole-database
-- re-resolution pass, spec 10.7.9). owner_raw is NULL for an unassigned phrase.
CREATE TABLE item_source_owner (
    item_source_id INTEGER NOT NULL REFERENCES item_source(id) ON DELETE RESTRICT,
    ordinal        INTEGER NOT NULL,
    owner_raw      TEXT,
    role           TEXT NOT NULL DEFAULT 'owner' CHECK (role IN ('owner', 'with')),
    person_id      TEXT REFERENCES person(id) ON DELETE RESTRICT,
    owner_status   TEXT NOT NULL CHECK (owner_status IN ('resolved', 'provisional', 'ambiguous', 'unassigned')),
    provenance     TEXT NOT NULL CHECK (provenance IN (
        'roster', 'alias', 'attendee', 'attendee_in_meeting', 'unique_first_name', 'initial_form',
        'diacritic_fold', 'provisional', 'none')),
    PRIMARY KEY (item_source_id, ordinal)
);

-- candidates is a JSON array of person ids sorted ascending (deterministic).
CREATE TABLE item_owner (
    item_id      INTEGER NOT NULL REFERENCES action_item(id) ON DELETE RESTRICT,
    ordinal      INTEGER NOT NULL,
    owner_raw    TEXT,
    role         TEXT NOT NULL DEFAULT 'owner' CHECK (role IN ('owner', 'with')),
    person_id    TEXT REFERENCES person(id) ON DELETE RESTRICT,
    owner_status TEXT NOT NULL CHECK (owner_status IN ('resolved', 'provisional', 'ambiguous', 'unassigned')),
    candidates   TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(candidates)),
    provenance   TEXT NOT NULL CHECK (provenance IN (
        'roster', 'alias', 'attendee', 'attendee_in_meeting', 'unique_first_name', 'initial_form',
        'diacritic_fold', 'provisional', 'none')),
    PRIMARY KEY (item_id, ordinal)
);

-- Storage rule (G-11): a possible_duplicate link is symmetric and stored ONCE with from_item_id < to_item_id
-- and is read from both ends. completed_by is directional: from = item whose completion was inferred,
-- to = item holding the done evidence. reason is NULL only where no reason applies (completed_by).
CREATE TABLE item_link (
    from_item_id INTEGER NOT NULL REFERENCES action_item(id) ON DELETE RESTRICT,
    to_item_id   INTEGER NOT NULL REFERENCES action_item(id) ON DELETE RESTRICT,
    kind         TEXT NOT NULL CHECK (kind IN ('possible_duplicate', 'completed_by')),
    reason       TEXT CHECK (reason IS NULL OR reason IN (
        'due_differs', 'owner_differs', 'status_differs', 'same_file', 'fuzzy', 'recurrence',
        'outside_window', 'owner_unresolved')),
    created_run  INTEGER REFERENCES ingest_run(id) ON DELETE RESTRICT,
    PRIMARY KEY (from_item_id, to_item_id, kind),
    CHECK (from_item_id <> to_item_id),
    CHECK (kind <> 'possible_duplicate' OR from_item_id < to_item_id)
);

CREATE TABLE item_event (
    id       INTEGER PRIMARY KEY AUTOINCREMENT,
    item_id  INTEGER NOT NULL REFERENCES action_item(id) ON DELETE RESTRICT,
    ts       TEXT NOT NULL,
    kind     TEXT NOT NULL CHECK (kind IN (
        'created', 'source_added', 'source_removed', 'merged', 'updated_from_source', 'status_changed',
        'owner_changed', 'manual_done')),
    "before" TEXT,
    "after"  TEXT,
    run_id   INTEGER REFERENCES ingest_run(id) ON DELETE RESTRICT
);

-- No body, subject or message text column exists on purpose (GM-10). item_ids and ambiguous_item_ids are
-- JSON arrays of item ids. source records who created the draft (actiontrack itself or the host session).
CREATE TABLE followup_draft (
    id                 INTEGER PRIMARY KEY AUTOINCREMENT,
    person_id          TEXT NOT NULL REFERENCES person(id) ON DELETE RESTRICT,
    channel            TEXT NOT NULL CHECK (channel IN ('handoff', 'google', 'fake')),
    item_ids_hash      TEXT NOT NULL,
    item_ids           TEXT NOT NULL CHECK (json_valid(item_ids)),
    include_ambiguous  INTEGER NOT NULL DEFAULT 0 CHECK (include_ambiguous IN (0, 1)),
    ambiguous_item_ids TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(ambiguous_item_ids)),
    handoff_path       TEXT,
    args_sha256        TEXT,
    gmail_draft_id     TEXT,
    thread_id          TEXT,
    view_url           TEXT,
    source             TEXT NOT NULL CHECK (source IN ('actiontrack', 'host')),
    status             TEXT NOT NULL CHECK (status IN (
        'pending_handoff', 'created_by_host', 'failed_by_host', 'created', 'failed', 'unknown')),
    created_at         TEXT NOT NULL,
    recorded_at        TEXT
);

CREATE INDEX idx_action_item_status_due ON action_item(status, due_date);
CREATE INDEX idx_item_owner_person ON item_owner(person_id);
CREATE INDEX idx_item_source_item ON item_source(item_id);
CREATE INDEX idx_item_source_file_present ON item_source(source_file_id, present);
